[
  {
    "name": "GPT-2 Factual Recall K=3 CSS (v2)",
    "description": "GPT-2 Small 上运行 country→capital factual recall（如 \"The capital of France is\" → \"Paris\"）。 K=3 方法（EAP-IG + EP + ACDC），top-50 binarization。MLP-based knowledge retrieval circuit 导致方法在 MLP bottleneck edges 上高度收敛，预期 max Jaccard > 0.5，CSS FAIL。\n",
    "results": {
      "binarization": "top-50",
      "edge_counts": {
        "eap_ig": 50,
        "ep": 50,
        "acdc": 50
      },
      "pairwise_jaccard": {
